# aeneid-084 (XI.225-335): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Responsa Diomedis. Concilium Latini'
PART = "Diomedes' Refusal and Latinus's Council (XI.225–335)"
TITLE_EN = "Diomedes' Refusal and Latinus's Council — Aeneid XI.225–335"
ABOUT = ("While the Latin city is still in turmoil over the dead and over Turnus, the envoys sent to Diomedes in Apulia come back empty-handed: neither gifts nor gold nor pleading has moved him, and the Latins must look for other allies or make peace with Aeneas. "
"King Latinus, shaken, summons a great council to his palace, and Venulus reports. "
"Diomedes, now building a city in the south of Italy, received them kindly but would not fight. "
"Every Greek who sacked Troy, he said, has paid for it: Ajax drowned off Caphareus, Menelaus driven to Egypt, Ulysses among the Cyclopes, Agamemnon cut down at his own door, and Diomedes himself kept from home, his companions turned into birds, all for the day he wounded Venus. "
"He has met Aeneas spear to spear and knows his strength; Aeneas and Hector together held Troy's fall back ten years. "
"Make peace with him, he advises, and give him the gifts. "
"A murmur runs through the hall like water breaking against rocks. "
"Then Latinus speaks: the war is against men of divine descent who cannot be beaten, the hope of Diomedes is gone, and he proposes to give the Trojans land to settle on, or, if they prefer to leave, to build them ships, and to send a hundred envoys with gifts and the emblems of royalty to offer a treaty. "
"Diomedes' memories of the Iliad, where he fought Aeneas and wounded Venus, are Virgil's way of letting a Greek witness praise his hero.")

U = [
(227, 'ferunt:',
 """Amid these commotions, in the middle of the blazing tumult,\nlo, on top of all, sad, from great Diomedes' city\nthe envoys the answers bring:""",
 """In the midst of this unrest, while the uproar was at its height, there came, to crown all, the envoys back from great Diomedes' city with gloomy faces, bringing his answer:""",
 """A new paragraph in Greenough. The story picks up from the grief and anger against Turnus at the end of the last part (215–224). 'Hos inter motus', the preposition placed between demonstrative and noun. 'medio in flagrante tumultu', 'in the blazing middle of the tumult'. 'ecce' brings the envoys in suddenly. 'super', adverb, 'besides, on top of everything'. 'maesti' agrees with 'legati', 'sad', and tells the news before it is given. 'magna Diomedis ab urbe', the adjective and noun framing the genitive. Venulus was sent to Diomedes at the start of Book VIII (VIII.9). The colon opens their report. Elision 'medi(o) in'."""),
(230, 'petendum.',
 """nothing by all had been achieved,\nby the outlays of so great efforts, nothing gifts nor gold\nnor great had availed prayers; other arms for the Latins\nmust be sought, or peace from the Trojan king must be sought.""",
 """that nothing had been gained by all their great and costly labours, that neither gifts nor gold nor earnest pleading had prevailed; the Latins must look for other allies, or else ask the Trojan king for peace.""",
 """The report in indirect speech, every 'esse' left out: 'nihil… actum (esse)', 'that nothing had been achieved'; 'nil… valuisse', 'that nothing… had availed', with 'nil' as an adverbial 'not at all'. 'omnibus… impensis', 'by all the outlay', ablative of means. 'alia arma Latinis quaerenda', 'other arms must be sought by the Latins', the gerundive of obligation with the dative of the agent. 'pacem… petendum', an old construction: the neuter gerundive used impersonally with a direct object, 'one must seek peace' (Lucretius has it often). 'arma' here means allies, armed help. Elisions 'tantor(um) impensis', 'nequ(e) aurum', 'ali(a) arma', 'quaerend(a) aut', 'Troian(o) ab'."""),
(231, 'Latinus.',
 """Fails under the huge grief the king himself, Latinus.""",
 """King Latinus himself sank under the weight of his grief.""",
 """'Deficit', 'fails, gives way', his strength and his resolve both. Putting the verb first makes the collapse the news; the subject comes last, 'rex ipse Latinus', 'the king himself', not only the people. 'ingenti luctu', ablative of cause, 'with (or under) great grief'. Latinus never wanted this war: in Book VII he gave up the reins of government when his people forced it on him (VII.591–600). No elisions."""),
(233, 'recentes.',
 """That fated Aeneas by manifest divine will is borne,\nwarns him the anger of the gods, and of the mound before his eyes the fresh ones.""",
 """The anger of the gods and the new graves before his eyes warned him that Aeneas was the man of destiny, carried on by a power of heaven plain for all to see.""",
 """Accusative and infinitive after 'admonet', 'warns (him) that': 'Aenean… ferri', 'that Aeneas is being carried along'. 'Aenean' is the Greek accusative of 'Aeneas'. 'Fatalem', 'fated, sent by fate', put first: the man fate has chosen. 'manifesto numine', 'by a manifest divine power'. Two subjects for one verb: 'ira deum' ('deum' = 'deorum', the old genitive plural) and 'tumuli… recentes', 'the fresh grave-mounds', the 'que' joining them; 'ante ora', 'before his eyes'. The defeat is itself a sign of the gods' will. Elisions 'Fatal(em) Aenean', 'tumuliqu(e) ante', 'ant(e) ora'."""),
(235, 'cogit.',
 """Therefore a council great and the first of his people\nby command summoned within the high threshold he assembles.""",
 """So he called a great council, summoning the leading men of his people by royal command within his lofty halls.""",
 """'Ergo', 'therefore', because he sees the gods against him. 'concilium magnum primosque suorum', two objects of 'cogit', 'gathers': the council and the chief men 'of his own (people)'. 'imperio accitos', 'summoned by (his) command', perfect participle of 'accio', 'call to'. 'alta intra limina', the preposition between the adjective and its noun again; 'limina', 'threshold', for the palace by synecdoche, the part for the whole. 'concilium', an assembly, not 'consilium', advice, though Latinus will ask for that too (335). Elisions 'imperi(o) accitos', 'alt(a) intra'."""),
(237, 'viis.',
 """They came together, and they stream to the royal, through full\nhouse, the streets.""",
 """They gathered, pouring through crowded streets towards the royal palace.""",
 """The print has 'olli' with a small letter after the full stop ending 235, a misprint for 'Olli', corrected here. 'olli' is the archaic form of 'illi', 'those men', nominative plural, an old word kept in epic for its solemn ring (you will meet it again). 'convenere' = 'convenerunt', the perfect in '-ere'. 'fluunt', 'flow', of a crowd moving like water. 'ad regia… tecta', 'to the royal roofs', the palace, with 'plenis… viis', 'through full streets', ablative of the way by which, wrapped round the line-break. Elision 'fluuntqu(e) ad'."""),
(238, 'Latinus.',
 """Sits in the middle both greatest in age\nand first in sceptres, with not glad brow, Latinus.""",
 """In their midst sat Latinus, first in years and first in royal power, and there was no gladness in his face.""",
 """'Sedet', vivid present, put first as 'Deficit' was at 231, with the name held to the end of the line. 'et maximus aevo et primus sceptris', 'both greatest in age and first in sceptres', ablatives of respect: he is the oldest and the highest in rank; 'sceptris', plural for singular, the royal staff standing for the power it signifies. 'haud laeta fronte', 'with a brow not glad', an understatement (litotes) for a grim face; ablative of manner or description. No elisions."""),
(241, 'suo.',
 """And here the envoys from the Aetolian city sent back,\nwhat they bring back, to speak he bids, and the answers he demands\nin its order all.""",
 """And now he bade the envoys sent back from the Aetolian city tell what news they brought, and asked for the answers in full, each in its proper order.""",
 """'Atque hic', 'and at this point'. 'Aetola ex urbe', Diomedes' city, called Aetolian because Diomedes' father Tydeus came from Calydon in Aetolia (see 270); Diomedes himself had ruled Argos. 'remissos', 'sent back', the envoys returning. 'quae referant', an indirect question, object of 'fari', 'to speak what they report'. 'iubet', 'bids', with the infinitive. 'reposcit', 'demands back', the 're-' because the answers are owed him. 'ordine cuncta suo', 'all things in their order', the king wants every detail. Elisions 'Atqu(e) hic', 'Aetol(a) ex'."""),
(242, 'infit:',
 """Then silence was made for tongues,\nand Venulus, to the command obeying, thus to speak begins:""",
 """Then all tongues fell silent, and Venulus, obeying the command, began to speak:""",
 """'facta silentia', 'silences were made', with 'sunt' left out; the plural is poetic. 'linguis', dative, 'for the tongues', that is, tongues were stilled. 'dicto parens', 'obeying the word', 'pareo' with the dative. 'farier' is the archaic present passive infinitive of 'for', 'speak', for 'fari', a form kept in epic for its old-fashioned dignity; it depends on 'infit', 'begins', an old verb found only in this form and a few others, always introducing speech. Venulus was sent to Diomedes at VIII.9. No elisions."""),
(245, 'tellus.',
 """“We have seen, O citizens, Diomedes and the Argive camp,\nand the road having measured out we have overcome the chances all,\nand we have touched the hand by which fell the Ilian land.""",
 """“We have seen Diomedes, citizens, and his Argive camp; we came through every danger of the long road, and we touched the hand that brought down the land of Ilium.""",
 """A new paragraph in Greenough, and the start of Venulus's report, which runs to 295 and quotes Diomedes' own words within it (252–293). 'Diomedem', Greek accusative. 'Argiva castra', 'the Argive camp': Diomedes was king of Argos, and his settlement still feels like an army's camp. 'iter emensi', 'having measured out the road', from 'emetior', a deponent, so the perfect participle is active. 'casus… omnis', 'all the hazards', '-is' accusative plural (Greenough's spelling throughout). 'contigimus manum', 'we touched the hand', as suppliants and as guests; 'qua concidit Ilia tellus', 'by which the land of Ilium fell', Diomedes was among the greatest Greek fighters at Troy. Elisions 'Diomed(em) Argivaque', 'atqu(e) iter'."""),
(247, 'agris.',
 """He the city Argyripa, after the surname of his ancestral race,\nvictorious, of Garganus Iapygian was founding in the fields.""",
 """He, a conqueror, was building a city called Argyripa after the people of his fathers, in the fields of Iapygian Garganus.""",
 """'Argyripam', the city named 'from the name of his native people': the Greek form of the name was taken as 'Argos Hippion', 'horse-rearing Argos', after Diomedes' Argos; the later town was Arpi (250), in Apulia in the south-east of Italy. 'condebat', 'was founding', imperfect, the work still going on. 'victor', 'as a victor', after Troy. 'Gargani… Iapygis agris', 'in the fields of Iapygian Garganus': Garganus is the mountainous headland of Apulia, and 'Iapyx' (genitive 'Iapygis', here an adjective) means Apulian, from the Iapyges, an old people of the region. Elisions 'Ill(e) urbem', 'urb(em) Argyripam'."""),
(250, 'Arpos.',
 """After we went in and in his presence was given chance of speaking,\nthe gifts we hold forth, our name and fatherland we tell,\nwho war have brought on, what cause has drawn us to Arpi.""",
 """When we had been let in and given leave to speak before him, we presented our gifts, and told him our name and our country, who had made war on us, and what had brought us to Arpi.""",
 """'Postquam introgressi (sumus) et… data (est) copia fandi', two verbs with their auxiliaries left out. 'coram', 'face to face, in person'. 'copia fandi', 'opportunity of speaking', 'fandi' the gerund of 'for'. 'praeferimus… docemus', vivid presents in narrative. 'nomen patriamque', 'our name and country', who we are. 'qui bellum intulerint, quae causa attraxerit', two indirect questions with perfect subjunctives, still objects of 'docemus': 'who have brought war (on us), what cause has drawn (us)'. 'Arpos', accusative of 'Arpi', plural place-name; the place of motion without a preposition. Elisions 'Postqu(am) introgressi', 'introgress(i) et', 'bell(um) intulerint', 'caus(a) attraxerit'."""),
(251, 'ore:',
 """Having heard, he these things with calm thus returned from mouth:""",
 """He listened, and with a calm face gave this reply:""",
 """'Auditis', ablative absolute with the noun understood, '(these things) having been heard', 'when he had heard'. 'haec… sic reddidit', 'he gave back these words thus', 'reddo' of a reply as something owed. 'placido… ore', 'with a calm face (or mouth)', 'os' meaning both. Diomedes' composure sets the tone for his answer, which is sympathetic but firm. Elision 'ill(e) haec'."""),
(254, 'bella?',
 """“O fortunate peoples, Saturnian kingdoms,\nancient Ausonians, what fortune you, quiet ones,\ntroubles and persuades unknown to provoke wars?""",
 """“O happy peoples, realm of Saturn, ancient Ausonians, what fortune is it that disturbs your peace and urges you to stir up wars you do not know?""",
 """Diomedes' words, quoted by Venulus; the print opens them with a second opening mark inside Venulus's speech and closes both with a single mark at 295. 'Saturnia regna', in apposition: Saturn, driven from heaven, ruled Latium in the golden age (VIII.319–325), and Italy is still the land of peace he left. 'Ausonii', an old name for the peoples of Italy. 'quietos', 'you who were quiet', a predicative adjective: fortune troubles you who were at peace. 'ignota… bella', 'wars you do not know', wars you have no experience of, as the Greeks have. 'lacessere' after 'suadet', 'persuades (you) to provoke', the infinitive in verse. Elisions 'antiqu(i) Ausonii', 'suadetqu(e) ignota'."""),
(259, 'manus:',
 """Whoever of us the Ilian with iron outraged fields,\n— I pass over those things which beneath the walls by warring were drained to the dregs, high,\nwhat men that Simois presses down — unspeakable throughout the world\npunishments and for crimes penalties we have paid out, all,\na band even to Priam to be pitied:""",
 """All of us who did violence with the sword to the fields of Troy — I say nothing of what we endured fighting under those high walls, or of the men who lie beneath the Simois — have paid, throughout the world, unspeakable punishments and the penalty for our crimes, a band that even Priam might pity:""",
 """The main clause is 'Quicumque… violavimus… expendimus omnes', 'all of us who violated… have paid'. A parenthesis interrupts it: 'mitto ea quae… exhausta (sunt)', 'I pass over what was drained to the dregs', endured to the end, 'bellando', 'by fighting', the gerund; 'quos Simois premat ille viros', 'what men that Simois holds down', an indirect question; Simois is a river of Troy, whose waters roll the dead (I.100–101, from the Iliad). 'ille', 'that famous'. 'expendimus', 'we paid out', of a debt. 'vel Priamo miseranda manus', 'a band to be pitied even by Priam', the enemy they ruined; 'Priamo', dative of agent with the gerundive. Elisions 'Quicumqu(e) Iliacos', 'mitt(o) ea', 'belland(o) exhausta', 'supplici(a) et'."""),
(260, 'Caphareus.',
 """knows it the grim of Minerva\nstar, and the Euboean crags, and avenging Caphareus.""",
 """the baleful star of Minerva knows it, and the Euboean crags, and Caphareus the avenger.""",
 """'scit', 'knows', put first, with three subjects that witnessed the Greeks' punishment. 'triste Minervae sidus', 'the grim star of Minerva', the storm she raised against the fleet because Ajax son of Oileus had dragged Cassandra from her temple; she struck him with a thunderbolt (I.39–45). 'sidus', a constellation, here a season of storms. 'Euboicae cautes', 'the Euboean crags', where the ships were wrecked. 'ultor… Caphareus', the headland of Euboea where Nauplius, avenging his son Palamedes, whom the Greeks had put to death, lit false beacons to lure the returning ships onto the rocks. 'Caphareus' ends the line with '-eus' read as one syllable. No elisions."""),
(263, 'Ulixes.',
 """From that campaign to a different shore driven off,\nAtreus's son Menelaus, of Proteus right to the pillars\nis exiled; the Aetnaean saw the Cyclopes Ulysses.""",
 """After that campaign, driven away to distant shores, Menelaus the son of Atreus lives in exile as far as the pillars of Proteus, and Ulysses has seen the Cyclopes of Etna.""",
 """'abacti', 'driven away', plural, refers to the Greeks in general, of whom Menelaus is one; the verb 'exsulat' is singular. 'diversum ad litus', 'to a different shore', each to his own. 'Atrides', 'son of Atreus', a Greek patronymic. 'Protei… columnas', 'the pillars of Proteus': Menelaus was carried to Egypt, where he caught the shape-shifting sea-god Proteus on the island of Pharos to learn his way home (Odyssey 4); the 'pillars' mark the furthest limit, as 'the pillars of Hercules' mark the West. 'Protei' is a Greek genitive, '-ei' read as one syllable. 'adusque', 'all the way to'. 'Aetnaeos… Cyclopas', the Cyclopes of Sicily, met by Ulysses in Odyssey 9 and by Aeneas in III.588–681. No elisions."""),
(265, 'Idomenei?',
 """The kingdom of Neoptolemus shall I tell, and the overturned household gods\nof Idomeneus?""",
 """Shall I tell of the kingdom of Neoptolemus, and of Idomeneus driven from his home?""",
 """'referam', deliberative subjunctive, 'am I to recount?', a way of passing over what everyone knows (as 'mitto', 256). 'Regna Neoptolemi', the kingdom of Achilles' son: he was killed by Orestes at Delphi, and part of his realm passed to Helenus (III.325–336). 'versos penates', 'overturned household gods', his home destroyed: Idomeneus, king of Crete, vowed in a storm to sacrifice the first thing he met on landing, met his own son, and was driven out of Crete by his people (III.121–122 tells of the exile). 'Idomenei', Greek genitive, the last two vowels read as one syllable. No elisions."""),
(265, 'Locros?',
 """Of Libya on the shore living the Locrians?""",
 """Or of the Locrians dwelling on the coast of Libya?""",
 """'Libycone… litore', the '-ne' on the first word asking the question, 'on the Libyan shore?'. 'habitantis… Locros', 'the Locrians dwelling', '-is' accusative plural of the participle. The Locrians were the men of Ajax son of Oileus; when he drowned (260), the story went that his followers were carried off to the coast of Africa and settled there. The list moves fast, one line or half-line to each disaster, each a story the Latins might know. Elision 'Libycon(e) habitantis'."""),
(268, 'oppetiit:',
 """Himself the Mycenaean, of the great leader of the Achaeans,\nof his wife unspeakable at the very threshold by the right hand\nmet death:""",
 """The very lord of Mycenae, leader of the mighty Greeks, met his death on his own threshold, at the hand of his accursed wife:""",
 """'Ipse', 'himself', the greatest of them all: Agamemnon, king of Mycenae, commander of the Greeks at Troy. 'Achivom' = 'Achivorum', old genitive plural ('divom', 'virum'). 'coniugis infandae… dextra', 'by the right hand of his unspeakable wife', Clytemnestra, who killed him with her lover Aegisthus on his return (Odyssey 11; Aeschylus's Agamemnon). 'prima inter limina', 'within the first threshold', at the very entrance of his house, as soon as he came home. 'oppetiit', 'met (death)', with 'mortem' understood, as often. Elision 'prim(a) inter'."""),
(268, 'adulter.',
 """conquered Asia lay in wait for the adulterer.""",
 """the adulterer lay in wait for the conqueror of Asia.""",
 """A bitter epigram. 'subsedit', 'lay in ambush for', from 'subsido', 'settle down, crouch in wait', taking an accusative. 'devictam Asiam', 'conquered Asia', stands for the man who conquered it, Agamemnon: Asia was defeated, and the adulterer, Aegisthus, took the victory from it. Some editors read 'possedit', 'took possession of', which changes the sense: 'the adulterer won what Agamemnon had conquered'. Greenough's reading is kept. Elision 'devict(am) Asiam'."""),
(270, 'viderem?',
 """To think the gods begrudged that, to my ancestral altars restored,\nmy longed-for wife and fair Calydon I should see!""",
 """And the gods would not even grant me this, to be restored to the altars of my fathers and see the wife I longed for and lovely Calydon?""",
 """An accusative and infinitive of indignation, set out as a question: 'Invidisse deos', '(to think) that the gods begrudged'; the pattern of 'Mene… desistere' (I.37). 'ut… viderem', the thing begrudged, imperfect subjunctive. 'patriis… aris', 'to my ancestral altars', dative with 'redditus', 'given back'. 'coniugium optatum', 'the longed-for marriage', his wife; the story was that Venus, to punish him, made his wife Aegiale unfaithful, so that he came home to find himself shut out and sailed for Italy. 'Calydona', Greek accusative: Calydon in Aetolia was the home of his father Tydeus. Elisions 'coniugi(um) optatum', 'optat(um) et'."""),
(274, 'implent.',
 """Now even, horrible to sight, portents follow,\nand my companions, lost, have sought the upper air on wings\nand on the rivers wander as birds — alas, dire of my men\nthe punishments! — and the cliffs with tearful voices they fill.""",
 """Even now portents, dreadful to behold, pursue me: my companions are lost to me, they have flown into the sky on wings and wander the rivers as birds — alas, the cruel punishment of my people! — and they fill the cliffs with their mournful cries.""",
 """'horribili visu', 'horrible to see', the supine in '-u' after an adjective. 'portenta sequuntur', 'portents follow (me)'. 'socii amissi', 'my lost companions', changed into birds; 'petierunt aethera pennis', 'sought the sky with wings'. 'petierunt', the full perfect, with '-erunt'. 'fluminibus', 'on (or along) the rivers', ablative of place. 'heu dira meorum supplicia', an exclamation thrown in, accusative or nominative of exclamation. The story is told in full by Ovid (Metamorphoses 14): the companions mocked Venus and became sea-birds, the 'birds of Diomedes', still said in antiquity to haunt the islands off Apulia that bore his name. Elisions 'eti(am) horribili', 'soci(i) amissi', 'supplici(a) et'."""),
(277, 'dextram.',
 """These things indeed from that to me already were to be expected\ntime, when with iron the heavenly bodies, madman,\nI attacked, and of Venus I violated with a wound the right hand.""",
 """All this I might have looked for, ever since that day when in my madness I went at the bodies of the gods with steel and outraged Venus's hand with a wound.""",
 """'adeo', emphasising 'haec', 'these very things'. 'speranda fuerunt', 'were to be expected', gerundive of obligation; 'spero' means 'expect', not only 'hope', and is used of evils too. 'ex illo… tempore', 'from that time', the phrase split across the line. 'caelestia corpora', 'heavenly bodies', the poetic plural for Venus alone. 'demens', 'out of my mind', he condemns himself. In Iliad 5 Diomedes, helped by Athena, wounded Aphrodite in the hand as she carried her son Aeneas out of the battle. 'adpetii', Greenough's spelling of 'appetii', 'I attacked'. 'volnere' = 'vulnere'. Elisions 'ade(o) ex', 'adpeti(i) et'."""),
(278, 'pugnas:',
 """Do not, truly, do not me to such urge battles:""",
 """No, do not, I beg you, drive me into such a war:""",
 """'Ne… impellite', 'do not urge', 'ne' with the imperative, an old and poetic form of prohibition (prose would use 'noli' with the infinitive or 'ne' with the perfect subjunctive). The repeated 'ne' and the emphatic 'vero', 'indeed, truly', make the refusal earnest. 'talis… pugnas', 'such battles', battles against a Trojan, '-is' accusative plural. Elision 'm(e) ad'."""),
(280, 'malorum.',
 """nor for me with the Teucrians any after the overthrown war\nPergamum, nor of the old do I remember or rejoice in evils.""",
 """I have no quarrel left with the Trojans now that Pergamum is overthrown, and I take no pleasure in remembering the evils of the past.""",
 """'nec mihi… ullum… bellum (est)', 'nor is there any war to me', the dative of possession: 'I have no war with the Teucrians'. 'post eruta… Pergama', 'after Pergamum overthrown', 'after the overthrow of Pergamum', the participle carrying the main idea, as in 'ab urbe condita'. Pergama is Troy's citadel, a neuter plural. 'memini laetorve', 'nor do I remember or rejoice in', both verbs taking the genitive 'veterum… malorum'. The sense is close to 'I neither dwell on nor gloat over'. No elisions."""),
(282, 'Aenean.',
 """The gifts, which from your ancestral to me you bring shores,\nturn to Aeneas.""",
 """The gifts you bring me from your native shores, turn them towards Aeneas.""",
 """'Munera', put first and picked up by the verb at the start of the next line: 'the gifts… turn them'. 'patriis… ab oris', 'from your native shores', the adjective and noun again framing the clause. 'vertite ad Aenean', 'turn (them) to Aeneas', use them to win peace from him, the advice his whole speech leads to. 'Aenean', the Greek accusative. Elision 'vertit(e) ad'."""),
(283, 'manus:',
 """We have stood his weapons rough against\nand we have joined hands:""",
 """I have stood against his savage weapons and met him hand to hand:""",
 """'Stetimus… contulimusque', the plural for the singular, 'I stood… I engaged'. 'tela aspera contra', 'against his rough weapons', the preposition placed after its noun (anastrophe). 'conferre manus', 'to join hands', to fight at close quarters. Diomedes means the duel in Iliad 5, where he struck Aeneas down with a great stone and would have killed him, but Aphrodite carried her son away; Virgil lets the Greek remember it as a fight between equals. Elision 'tel(a) aspera'."""),
(284, 'hastam.',
 """believe one who has tried, how great\ninto his shield he rises, with what whirlwind he hurls the spear.""",
 """believe me, who have tried it: how tall he rises behind his shield, with what a whirlwind he flings his spear!""",
 """'experto credite', 'believe one who has tried it', dative of the perfect participle of 'experior', a proverbial phrase: trust the man who knows. 'quantus… adsurgat, quo turbine torqueat', indirect questions with the subjunctive, depending loosely on 'credite', or exclamations: 'how great he rises', 'with what whirlwind he hurls'. 'in clipeum adsurgat', 'rises into his shield', draws himself up behind it for the blow. 'turbine', 'whirl', the spinning force of the throw. Elision 'clipe(um) adsurgat'."""),
(287, 'fatis.',
 """If two besides such had the Idaean borne\nland men, of its own accord to the Inachian would have come cities\nDardanus, and with fates turned Greece would be mourning.""",
 """If the land of Ida had brought forth two more such men, the Trojans would have carried the war to the cities of Inachus themselves, and it would be Greece that mourned, with the fates reversed.""",
 """A condition contrary to fact: 'Si… tulisset… venisset… lugeret', pluperfect subjunctives for the past, then an imperfect, 'would (now) be mourning', for the present result. 'Idaea terra', 'the land of Ida', Troy, from the mountain above it. 'ultro', 'actually, unprovoked', taking the offensive. 'Inachias… ad urbes', 'to the Inachian cities', the cities of Argos, whose first king was the river-god Inachus. 'Dardanus', the founder of Troy's line, standing for his people. 'versis… fatis', ablative absolute, 'the fates being reversed'. In Iliad 6, too, Hector and Aeneas are named as the Trojans' best. Elision 'ultr(o) Inachias'."""),
(290, 'annum.',
 """Whatever by the hard there was delay walls of Troy,\nby Hector's and Aeneas's hand the victory of the Greeks\nstuck, and to the tenth its steps carried back year.""",
 """Whatever delay there was before the walls of stubborn Troy, it was by the hands of Hector and Aeneas that the Greeks' victory was held fast and its coming put off to the tenth year.""",
 """'Quidquid… cessatum est', 'whatever delay there was', literally 'whatever was delayed', the impersonal passive of 'cesso'. 'durae… Troiae', 'hard Troy', unyielding. 'Hectoris Aeneaeque manu', 'by the hand of Hector and Aeneas', one hand for both. 'victoria Graium', 'the victory of the Greeks', 'Graium' = 'Graiorum', the old genitive plural. 'haesit', 'stuck fast', and 'vestigia rettulit', 'drew back its steps': victory is a figure who stalls and retreats. 'in decimum… annum', 'into the tenth year'. Elision 'cessat(um) est'."""),
(292, 'prior.',
 """Both in courage, both distinguished in outstanding arms;\nthis one in piety first.""",
 """Both were brave, both famed for their prowess in arms; but this one stood first in devotion.""",
 """'Ambo', repeated, with 'insignes' for both: 'both (distinguished) in courage, both distinguished in outstanding arms', ablatives of respect. The print has no stop after 'armis', so the two lines run on; most editions put a semicolon there, and the reading text marks the pause. 'hic', 'this one', Aeneas, the last named. 'pietate prior', 'superior in pietas', his sense of duty to gods, father and people, the quality the poem gives him from the start (I.10). The enemy grants him the virtue that defines him. Elisions 'Amb(o) animis', 'amb(o) insignes'."""),
(293, 'datur;',
 """Let them come together in treaties, your right hands,\nwhere it is granted;""",
 """Let your hands be joined in a treaty, in whatever way you can;""",
 """'Coeant… dextrae', jussive subjunctive, 'let right hands come together', the clasp of an agreement. 'in foedera', 'into treaties', poetic plural. 'qua datur', 'in whatever way it is allowed', literally 'by which way it is given': make peace on any terms you can. 'Coeant' is two syllables in the verse, 'coe-' read as one. No elisions."""),
(293, 'cavete.',
 """but that with arms clash arms, beware.""",
 """but beware of letting arms clash with arms.""",
 """'ast', an archaic form of 'at', 'but', kept in epic. 'cavete… concurrant', 'beware (lest) they clash', 'caveo' with the subjunctive and no 'ne', a colloquial and old construction. 'armis… arma', the same noun twice, side by side with the verb between, the clash shown in the words. This is the last of Diomedes' words; the print marks no close, and 294–295 return to Venulus. No elisions."""),
(295, 'bello.”',
 """Both the answers at the same time what they are, best king, of the king\nyou have heard, and what is his opinion on the great war.”""",
 """And so, best of kings, you have heard at once the king's answer and what he thinks of this great war.”""",
 """Venulus speaks again in his own person, addressing Latinus. The print puts a single closing mark here for both speeches, Diomedes' and Venulus's: Diomedes' words end at 293. 'Et… et', 'both… and': 'quae sint… responsa regis', 'what the answers of the king are', and 'quae sit… sententia', 'what his opinion is', two indirect questions. 'rex optime, regis', the vocative and the genitive set side by side, Latinus and Diomedes. 'magno… bello', dative, 'for the great war', or ablative, 'on the war'. Elision 'audist(i) et'."""),
(297, 'fremor:',
 """Scarcely these things the envoys, and a varied through the mouths ran,\nof the Ausonians, troubled, roaring:""",
 """The envoys had scarcely finished, when a confused murmur of alarm ran from mouth to mouth among the Ausonians:""",
 """A new paragraph in Greenough. 'Vix ea legati', with the verb of speaking left out, '(had) scarcely (said) these things', the ellipsis seen at I.37 and often. 'varius… fremor', 'a varied roar', a noise of many voices saying different things; the adjective and noun stand at either end, 'turbata', 'troubled', agrees with 'fremor'. 'per ora cucurrit', 'ran through the mouths'. 'Ausonidum', genitive plural of 'Ausonides', 'the sons of Ausonia', with the short '-um' ending. The colon opens a simile. No elisions."""),
(299, 'undis.',
 """as when rocks delay\nrapid rivers, there is from the shut-in pool a murmur,\nand the neighbouring roar banks with the crackling waves.""",
 """just as when rocks check a rushing river, the water is dammed into a pool and rumbles, and the banks nearby resound with the splashing of the waves.""",
 """'ceu… cum', 'as when', the usual opening of a simile, here with the order displaced: 'cum' stands at the head of the next line. 'saxa morantur… amnis', 'rocks delay rivers', '-is' accusative plural. 'fit… murmur', 'a murmur arises'; 'clauso gurgite', ablative absolute or of cause, 'the eddy being shut in'. 'crepitantibus undis', 'with clattering waves', the sound effect of the line. The Latins' unrest is like a stream checked by rocks; the simile has its ancestors in Homer's river similes, but no single model. 'vicinae' agrees with 'ripae'. No elisions."""),
(301, 'alto:',
 """As soon as were calmed the spirits and the anxious mouths fell quiet,\nhaving first addressed the gods, from the throne the king begins high:""",
 """As soon as their spirits were calmed and their anxious voices hushed, the king, after first calling upon the gods, began to speak from his lofty throne:""",
 """'Ut primum', 'as soon as', with the perfect ('placati (sunt)', 'quierunt' = 'quieverunt'). 'trepida ora', 'their anxious mouths', their agitated talk. 'praefatus divos', 'having first addressed the gods', 'praefari' of a preliminary prayer before public business, a Roman custom: magistrates began a meeting of the senate with prayer. 'solio… ab alto', 'from his high throne', the adjective and noun framing 'rex infit'. 'infit', 'begins', always of speech, as at 242. Elisions 'placat(i) animi', 'anim(i) et', 'trepid(a) ora'."""),
(304, 'hostis.',
 """“Before, indeed, about the highest matter to have decided, Latins,\nboth I should wish and it had been better, not in time such\nto gather a council, when the walls besets the enemy.""",
 """“I could have wished, Latins, and it would have been better, that we had settled this great question earlier, and not called a council at such a time as this, when the enemy is sitting before our walls.""",
 """Latinus's speech runs to the end of the part (335). 'Ante… statuisse', 'to have decided earlier', perfect infinitive after 'vellem', 'I should wish', the imperfect subjunctive of an unfulfilled wish. 'fuerat melius', 'it had been better', the pluperfect indicative used, as often with words of duty or fitness, where English says 'would have been'. 'summa de re', 'about the supreme matter', war or peace. 'cogere concilium', the second subject: 'not to call the council at such a time'. 'adsidet', 'sits by, besieges', with the accusative 'muros'; Greenough's spelling of 'assidet'. Elisions 'Ant(e) equidem', 'vell(em) et'."""),
(307, 'proelia:',
 """A war untimely, citizens, with a race of gods\nand unconquered men we are waging, whom no weary\nbattles:""",
 """We are waging an ill-starred war, citizens, against a race born of gods, against men no one can conquer and no battle can wear out:""",
 """'importunum', 'ill-timed, unsuitable', a war that should never have been fought. 'cum gente deorum', 'with a race of gods': Aeneas is the son of Venus, and the Trojans descend through Dardanus from Jupiter. 'invictis… viris', 'unconquered men'. 'quos nulla fatigant proelia', 'whom no battles weary', a relative clause in the indicative, stating a fact. 'proelia' is held over to the start of the next line, and the colon after it introduces the explanation. Elision 'Bell(um) importunum'."""),
(307, 'ferro.',
 """nor beaten can they withdraw from the sword.""",
 """even when beaten, they cannot be kept from the sword.""",
 """'nec victi', 'not even when beaten', 'victi' a participle with concessive force. 'absistere ferro', 'to stand back from the sword', 'absisto' with the ablative of separation. The Trojans were beaten at Troy and still came back to fight; Latinus has learned what Diomedes said. No elisions."""),
(309, 'ponite.',
 """Hope if any in the called-in of the Aetolians you have had arms,\nlay it down.""",
 """If you had any hope in the arms of the Aetolians as our allies, put it away.""",
 """'Spem siquam… habuistis', 'if you have had any hope', 'siquam' = 'si quam', 'quam' being the indefinite after 'si'. 'adscitis… in armis', 'in arms called in (from outside)', the allies the embassy went to fetch; 'adscisco', 'take in, adopt', in Greenough's unassimilated spelling (the Latin Library prints 'ascitis'). 'Aetolum' = 'Aetolorum', old genitive plural: Diomedes and his men (see 239). 'ponite', 'put down', abrupt at the start of the line, after the long conditional clause. Elisions 'siqu(am) adscitis', 'Aetol(um) habuistis'."""),
(309, 'videtis;',
 """Hope to himself each man, but this how narrow you see;""",
 """Each man must be his own hope; but you see how slender a hope that is;""",
 """'Spes sibi quisque', '(is) each man to himself a hope', the verb left out, almost a proverb: each must rely on himself. 'sed haec quam angusta', 'but how narrow this (hope is)', an indirect question with the verb again left out, object of 'videtis'. 'haec' agrees with the understood 'spes'. The line is hard to scan because a monosyllable, 'quam', is elided. Elision 'qu(am) angusta'."""),
(311, 'vestras.',
 """the rest, by what of things they lie struck down ruin,\nbefore your eyes and between your hands are all, yours.""",
 """as for the rest, the ruin that has struck everything down lies before your eyes and within your grasp.""",
 """The order is tangled: 'cetera… omnia', 'all the rest', is the subject of 'sunt'; 'qua rerum… perculsa ruina iaceant', an indirect question, 'by what ruin of our fortunes they lie struck down'. Read: 'all else, and the ruin of our state by which it lies crushed, is before your eyes and in your hands'. 'ante oculos interque manus', 'before your eyes and between your hands', you can see it and touch it. 'manus… vestras', the adjective at the very end. Elision 'ant(e) oculos'."""),
(312, 'incuso:',
 """Nor anyone do I accuse:""",
 """I do not blame anyone:""",
 """'incuso', 'accuse, find fault with'. Latinus, unlike the grieving people (215–219), will not blame Turnus or the army; a king trying to calm a council before proposing peace. The colon introduces the reason. Elision 'quemqu(am) incuso'."""),
(313, 'fuit;',
 """that which the greatest valour could\nbe, was;""",
 """all the courage there could be has been shown;""",
 """'potuit quae plurima virtus esse, fuit', 'the most valour that could be, was', that is, as much valour as was possible has been shown. 'quae plurima', the relative with a superlative, 'the greatest which', the antecedent 'virtus' drawn into the relative clause. 'fuit' at the start of the line, short and final. No elisions."""),
(313, 'regni.',
 """with the whole there was fighting body of the kingdom.""",
 """the kingdom has fought with all its strength.""",
 """'certatum est', impersonal passive, 'there has been fighting', 'we have fought'. 'toto… corpore regni', 'with the whole body of the kingdom', every part of the state, as one body, has put its strength into the struggle. Elision 'certat(um) est'."""),
(315, 'docebo.',
 """Now then, what is of my doubtful the opinion mind,\nI will set out, and in few words, your minds turn here, I will tell.""",
 """Now then I will lay out what my wavering mind has come to, and, if you will give me your attention, I will tell you in a few words.""",
 """'adeo', strengthening 'nunc', 'now then, now at last'. 'quae sit… sententia', 'what the opinion is', indirect question, with 'dubiae… menti', 'to my doubting mind', dative of possession: what my mind, hesitant as it is, has decided. 'expediam', 'I will unfold, set out'. 'paucis', '(in) a few (words)', the noun left out, a common idiom. 'animos adhibete', 'apply your minds', a parenthesis asking for attention. Elision 'expedi(am) et'."""),
(317, 'Sicanos;',
 """There is an ancient field to the Tuscan to me nearest river,\nlong toward the setting sun, the borders beyond as far as the Sicanians;""",
 """I have an ancient tract of land close by the Tuscan river, stretching far to the west beyond the borders of the Sicanians;""",
 """'Est… mihi', 'there is to me', dative of possession, 'I have'. 'ager', 'land, territory', crown land of the king. 'Tusco… amni', 'the Tuscan river', the Tiber, which divided Latium from Etruria; dative with 'proximus', 'next to'. 'longus in occasum', 'long towards the setting sun', stretching west. 'finis super usque Sicanos', 'beyond, all the way past the boundaries of the Sicanians', 'finis' accusative plural; the Sicani were thought to be early inhabitants of Latium before they went to Sicily. The exact geography is uncertain. No elisions."""),
(319, 'pascunt.',
 """The Auruncans and Rutulians sow, and with the ploughshare the hard\nwork hills, and of these the roughest they graze.""",
 """the Auruncans and Rutulians sow it, working the stubborn hills with the plough, and pasture their flocks on the roughest of them.""",
 """'serunt', from 'sero', 'sow', the land is farmed by neighbouring peoples: the Aurunci, an old people of Latium, and the Rutulians, Turnus's own people. 'vomere… exercent', 'they work with the ploughshare'; 'duros… colles', 'hard hills', framing the phrase. 'horum asperrima pascunt', 'they graze the roughest parts of these (hills)', 'pasco' with the accusative of the land grazed. The land is poor, but there is plenty of it. Elisions 'atqu(e) horum', 'hor(um) asperrima'."""),
(322, 'vocemus.',
 """This whole region and of the high the pine-clad tract mountain\nlet it yield to the friendship of the Teucrians, and of a treaty fair\nlet us declare the terms, and as allies into the kingdom call them.""",
 """Let this whole region, with its stretch of pine forest on the high mountain, be given up for the sake of friendship with the Trojans; let us set out fair terms of a treaty and invite them as partners in our kingdom.""",
 """The proposal, in jussive subjunctives: 'cedat', 'let it yield', 'dicamus', 'let us declare', 'vocemus', 'let us call'. 'plaga pinea', 'the piny tract', the forested part 'celsi… montis', 'of a high mountain'. 'amicitiae Teucrorum', dative, 'yield to the friendship of the Teucrians', be ceded as the price of friendship. 'foederis aequas… leges', 'fair terms of a treaty', 'leges' in the sense of conditions. 'socios', predicative, 'as allies'; 'in regna', 'into (a share of) the kingdom', poetic plural. Elisions 'regi(o) et', 'Teucror(um) et', 'sociosqu(e) in'."""),
(323, 'condant.',
 """Let them settle, if so great desire, and walls let them found.""",
 """Let them settle there, if they want it so much, and build their walls.""",
 """'Considant… condant', jussive subjunctives, 'let them settle… let them found'. 'si tantus amor (est)', 'if (they have) so great a desire', the verb left out: if they are so set on a home in Italy. 'moenia condant', building walls is founding a city, which is what Aeneas has been seeking since I.5. No elisions."""),
(325, 'nostro:',
 """But if other borders and another to reach for nation\nis their mind, and they are able from the soil to depart our:""",
 """But if they have it in mind to seek other lands and another people, and are free to leave our soil,""",
 """'Sin', 'but if', the alternative. 'est animus', 'it is (their) intention', with the infinitive 'capessere', 'to make for, seize'. 'alios finis aliamque… gentem', 'other borders and another people', '-is' accusative plural; 'alios… aliam' repeated for emphasis. 'possunt… decedere', 'are able to withdraw', that is, if fate does not hold them here. 'solo… nostro', 'from our soil', ablative of separation. The colon introduces what Latinus will then do. No elisions."""),
(329, 'demus.',
 """twice ten of Italian let us build of oak ships,\nor more to fill if they are able; lies all at the water\nthe timber; they themselves the number and the measure for the keels\nlet them prescribe; let us bronze, hands, dockyards give.""",
 """let us build them twenty ships of Italian oak, or more, if they can man them; the timber all lies ready by the water; let them lay down the number and design of the hulls, and we will supply the bronze, the workmen and the yards.""",
 """'bis denas… navis', 'twice ten ships', the distributive numeral; 'navis', '-is' accusative plural. 'texamus', 'let us weave', the regular verb for building ships, planks fitted like a fabric. 'Italo… robore', 'of Italian oak'. 'seu pluris complere valent', 'or if they can fill more', crew more ships. 'iacet… materies', 'the timber lies', ready. 'numerumque modumque', 'both number and size', 'carinis', 'for the keels', the ships. 'aera manus navalia', three nouns without connectives: 'bronze (for the fittings and beaks), hands, dockyards'. The print sets no stops after 'navis' or 'materies', so the lines run on; the reading text marks the pauses. No elisions."""),
(334, 'nostri.',
 """Besides, to carry the words and to make firm the treaty,\na hundred envoys from the first of the race, Latins,\nto go it pleases, and of peace in the hand to hold out the branches,\nbearing gifts, and of gold and of ivory talents,\nand the chair of the kingdom and the robe, emblems of ours.""",
 """Further, I resolve that a hundred envoys of the noblest Latin families shall go to carry our words and seal the treaty, holding out the branches of peace in their hands and bearing gifts, talents of gold and of ivory, and the throne and robe that are the emblems of our royalty.""",
 """'qui… ferant et… firment', a relative clause of purpose, 'to carry… and to confirm'. 'oratores', 'spokesmen, envoys', as at 100. 'prima de gente', 'from the foremost of the people'. 'ire placet', 'it pleases (me) that they go', the formal language of a decree. 'pacis… ramos', 'the branches of peace', olive branches, as the Latin envoys carried at 101. 'portantis', '-is' accusative plural agreeing with 'oratores'. 'talenta', 'talents', a Greek weight. 'sellam… trabeamque', the ivory chair and the striped robe, emblems of kingship that Rome later gave its magistrates; Latinus offers Aeneas a share of his royalty. Elisions 'cent(um) oratores', 'auriqu(e) eborisque', 'trabeamqu(e) insignia'."""),
(335, 'fessis.”',
 """Consult for the common good, and the affairs help weary.”""",
 """Take counsel for the common good, and come to the aid of our weary state.”""",
 """'Consulite in medium', 'consult into the middle', for the common good, 'medium' being what lies before all. 'rebus… fessis', 'our weary fortunes', the state worn out by war, dative with 'succurrite', 'run to help'. The council is opened to debate; Drances will speak next, and then Turnus. Elisions 'Consulit(e) in', 'medi(um) et'."""),
]

# Speech-mark check: Greenough opens Diomedes' words (252) with a second “ inside Venulus's speech (243) and closes
# both with one ” at 295; l and i follow the print exactly, so the counts match unit by unit and no exemption is needed.
EXEMPT = set()
P = A.part('aeneid-084'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
    if t.rstrip('”]')[-1] not in A.TERMINAL + ',': print('ENDING', ln, repr(t[-12:]))
    nw = len(n.split())
    if nw > 139 or nw < 15: print('NOTE LENGTH', ln, nw)
    for mk in '“”[]':
        if t.count(mk) != l.count(mk) and ln not in EXEMPT: print('MARK l', ln, mk)
        if mk in '“”' and t.count(mk) != i.count(mk) and ln not in EXEMPT: print('MARK i', ln, mk)
    if '“' in n or '”' in n: print('DOUBLE MARK IN n', ln)
covered = sorted({ln + k for (t, ln) in cuts for k in range(t.count('\n') + 1)})
if covered != [l['n'] for l in L]: print('COVERAGE', covered)
joined = '\n'.join(l['t'] for l in L)
rebuilt = ''.join(t + ('\n' if (k + 1 < len(cuts) and cuts[k + 1][1] != ln + t.count('\n')) else ' ' if k + 1 < len(cuts) else '') for k, (t, ln) in enumerate(cuts))
if rebuilt != joined: print('JOIN MISMATCH')
if A.sha(L) != P.get('sha256', A.sha(L)): print('SHA MISMATCH')
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units;', len(covered), 'lines covered')
